window.MONSTER_CHUNK_143 = [{"name":"Thundershrike","cr":9,"xp":6400,"alignment":"N","size":"Huge","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":19,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+2 Dex, +9 natural, -2 size","hp":136,"hd":"13d10+65","hdvalue":13,"fort":13,"ref":10,"will":1,"speed":[{"type":"land","speed":20},{"type":"fly","speed":70,"maneuverability":"average"}],"melee":"2 claws +19 (1d8+8), bite +20 (2d6+8)","space":"15 ft.","reach":"10 ft.","spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"gust of wind"}]},{"frequency":"1/day","spells":[{"spell":"control weather"}]},{"frequency":"2/day","spells":[{"spell":"lightning bolt","details":"half"}]}],"strength":26,"dexterity":15,"constitution":20,"intelligence":13,"wisdom":16,"charisma":17,"baseatk":13,"cmb":0,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Wingover"}],"skills":[{"skill":"Fly","value":8},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":17},{"skill":"Spellcraft","value":12},{"skill":"Survival","value":10}],"languages":["Auran","Common"],"environments":["temperate mountains"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"A tremendous winged shadow falls from a huge raptor with a wingspan the length of four horses. Its ebon feathers gleam majestically, streaked with patterns of gray and brown. Its golden beak is tipped with white.","source":"Tome of Horrors Complete (3pp)","description":"A thundershrike is an eagle-like raptor, perhaps in some way related to rocs, with a wingspan of upwards of 40 ft. Riding the winds with its massive wings spread wide, the thundershrike is thought by some cultures to be a herald of the gods of the thunderstorms. Thundershrikes are often found in the company of storm giants.\n\nThundershrikes get their name from their habit of taking to the air during powerful storms. Wind and rain follow the wings of a thundershrike.\n\nOften worshipped by barbarians and other wilderness dwellers, the thundershrikes are a proud species that view all that they survey as their territory. Although they keep their nests in isolated aeries in the high mountains, thundershrikes can range several hundred miles in search of food.\n\nThundershrikes mate for life, and females usually lay a clutch of 2d4 eggs in the spring. The eggs hatch in the late summer during the height of the storm season. Young remain in the nest for several months before venturing out on their own in the world.\n\nUnless it is on the hunt, a thundershrike is content to ride the winds and generally leave other creatures alone. If hunting, the thundershrike attacks any creature of Large or smaller size that appears tasty.\n\nA thundershrike opens combat with its lightning bolts before swooping or diving at a foe. It rarely lands during melee, preferring to attack from the air, using its spell-like abilities, and its snatch and hover to pick up and separate multiple foes. Female or mated thundershrikes will fight to the death to defend their nest or young.","ecology":"","habitat_society":""},{"name":"Tombstone Fairy","cr":9,"xp":6400,"alignment":"NE","size":"Small","type":"fey","init":8,"senses":[{"type":"low-light vision"}],"ac":18,"ac_touch":16,"ac_flat_footed":13,"ac_mods":"+4 Dex, +1 dodge, +2 natural, +1 size","hp":82,"hd":"15d6+30","hdvalue":15,"fort":9,"ref":13,"will":5,"dr":"10/good and cold iron","sr":20,"speed":[{"type":"land","speed":20}],"melee":"dagger +12 (1d3-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"danse macabre"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"suggestion"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"dancing lights"},{"spell":"death ward"},{"spell":"deathwatch"},{"spell":"desecrate"},{"spell":"detect chaos"},{"spell":"detect evil"},{"spell":"detect law"},{"spell":"detect thoughts"},{"spell":"dispel magic"},{"spell":"protection from good"}]}],"strength":9,"dexterity":19,"constitution":14,"intelligence":16,"wisdom":17,"charisma":20,"baseatk":7,"cmb":-1,"cmb_special":"+4 vs. dirty trick, +8 vs. steal","cmd":6,"cmd_special":"+2 vs. steal","feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":23},{"skill":"Craft (any)","value":11},{"skill":"Diplomacy","value":23},{"skill":"Escape Artist","value":22},{"skill":"Heal","value":18},{"skill":"Intimidate","value":20},{"skill":"Knowledge (religion)","value":8},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":25},{"skill":"Stealth","value":26}],"languages":["Common","Elven","Sylvan"],"environments":["any (cemeteries)","any (graveyards)","any (mausoleums)"],"organizations":["solitary","pair","throng (3-5)"],"treasure":"standard","description_visual":"This wicked little creature is dressed in the garb of an undertaker and resembles a tiny gargoyle. It has tiny black close set eyes, and its skin is slate gray.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Danse Macabre","kind":"Su","details":"Once per night, a tombstone fairy can invoke a ritual to raise any evil creature from the dead. The ritual takes 10 minutes to perform and the target cannot have been dead longer than one day per HD of the tombstone fairy. Additionally, the target's body must be present during the ritual and its soul must be available for return (that is, if the target's soul is trapped, such as by a trap the soul spell, this ritual automatically fails). A target unwilling to return to life can prevent its raising by making an opposed Charisma check against the tombstone fairy's Charisma check. If the tombstone fairy wins the check, the target's soul is forced into its body and it returns to life. If the target wins the opposed check, it prevents its raising, and the tombstone fairy cannot attempt to raise that same target for one month. During the ritual a portion of the target's soul transfers to its funeral shroud or cloth. The tombstone fairy often retains this shroud so as to force compliance from the returned target. Once the target does what the fairy desires, the tombstone fairy finishes this ritual and transfers the last bit of the target's soul from the shroud into its body. If the funeral shroud is destroyed while it contains a part of the target's soul, the target instantly dies and can only be returned to life through the use of a resurrection, true resurrection, miracle or wish. This ability otherwise resembles a raise dead spell. A tombstone fairy can have only one funeral shroud (containing a target's soul) in its possession at one time."}],"description":"Tombstone fairies are wicked beings that dwell within graveyards, raising murderers and evil heroes from the dead to go out and continue their deadly work. They often demand some form of repayment for the raising of such beings, keeping the creature's funeral shroud as a bargaining chip. This payment could range from magical or monetary treasures, the murder of a specific enemy and so on. Failure to make payment within 30 days usually results in the raised individual dying again. Upon payment, the formerly dead is given their shroud and is free to go about committing whatever foul deeds they wish.\n\nTombstone fairies are generally solitary creatures, but on occasion a small group of them comes together with a single goal: raise a small band of evil dead to further the fairies' own ends.\n\nA tombstone fairy stands about 3 ft. tall and weighs around 35 pounds.\n\nIts skin is always slate gray and its hair is either dark brown or black. Its eyes are always black.\n\nWhen pressed into combat, tombstone fairies fight with their wicked boning knife and spell-like abilities, seeking escape as quickly as possible.\n\nIf cornered, they fight to the death.","ecology":"","habitat_society":""},{"name":"Undead Raven Swarm","cr":9,"xp":6400,"alignment":"NE","size":"Tiny","type":"undead","subtypes":["swarm"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":16,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 Dex, +2 natural, +2 size","hp":105,"hd":"14d8+28 (+14)","hdvalue":14,"fort":8,"ref":8,"will":13,"defensive_abilities":["half damage from piercing and slashing"],"immunities":["swarm traits","undead traits"],"weaknesses":["swarm traits"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"swarm (3d6 plus eye-rake plus disease)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 18"},{"type":"eye-rake","details":"DC 18"}],"strength":2,"dexterity":15,"intelligence":2,"wisdom":15,"charisma":12,"baseatk":10,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":24}],"environments":["any"],"organizations":["solitary","unkindness (2-4 swarms)","murder (5-10 swarms)"],"treasure":"none","description_visual":"A screeching cawing whirlwind of buffeting wings, clawing talons and pecking beaks.","group":"Undead Raven","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disease","kind":"Su","details":"Raven plague: Swarm-injury; save Fort DC 18; onset 1 day; frequency 1/day; effect 1d4 Con damage and 1d2 Str damage; cure 2 consecutive saves. The save DC is Charisma-based."}],"description":"An undead raven swarm is a teeming mass of sinister, rotting, diseaseridden birds that seek to destroy any living creature encountered. A single undead raven appears as a rotting and diseased black bird whose feathers are torn, matted and dirty. Its eyes are inky black.\n\nUndead raven swarms are found in desolate forests, on desolate plains or moors, or in haunted caves and mountains.","ecology":"","habitat_society":""},{"name":"Well Lurker","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"aberration","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":21,"ac_touch":9,"ac_flat_footed":21,"ac_mods":"+12 natural, -1 size","hp":114,"hd":"12d8+60","hdvalue":12,"fort":9,"ref":6,"will":9,"dr":"5/-","speed":[{"type":"land","speed":10}],"melee":"6 tentacles +15 (1d8+4 plus grab), bite +16 (2d8+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"swallow whole","details":"2d8+8 plus 8 acid damage, AC 16, 25 hp"}],"strength":26,"dexterity":11,"constitution":20,"intelligence":4,"wisdom":13,"charisma":7,"baseatk":9,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":28,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Improved Grapple"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Perception","value":20}],"environments":["any underground"],"organizations":["solitary"],"treasure":"incidental","description_visual":"An open well-like hole surrounded by a crenellated edge hides the devouring mouth and lashing tentacles of this creature.","source":"Tome of Horrors Complete (3pp)","description":"These creatures make their homes in crevasses and carved dungeon pits. This creature has developed a keen natural camouflage making them appear as a freshwater well carved into subterranean lairs. The entire well is in fact the beast with tentacles and devouring mouth drawn five ft. beneath a rocky collar which protrudes from the ground.\n\nWell lurkers are opportunistic and passive hunters, rarely seeking out their meals; they simply wait for something to wander too close to them and then strike. If food becomes scarce or the area around a well lurker's lair becomes devoid of life, it uproots itself and moves to a new location.\n\nSuch occurrences are rare however as the well lurker can go months without eating (and its rare for caves and caverns to go months without being explored by adventurer types).\n\nA typical well lurker covers a 10-foot area, though specimens covering as much as a 30-foot area have been reported. A well lurker's tentacles are deep brown in color and about 10 ft. long (longer on larger specimens).\n\nIts maw is dark brown and ringed with many small tentacles. It can draw its grasping tentacles into its form and fold its mouth tentacles backwards inside its maw, thus appearing for all intents and purposes as an ancient stone well.\n\nAnimals can detect the unnatural presence of a well lurker and are generally nervous in its presence. Unless forced, an animal doesn't approach closer than 10 ft. to this creature.\n\nThis monster's tactics are simple. It waits for beings to attempt to draw water from the apparently bottomless depth before lashing out with tentacles, attempting to draw prey into its fanged mouth, biting and devouring foes whole. Cutting oneself out from the well lurker is nearly impossible as they brace their girth against solid stone, meaning one would have to climb out through the mouth of the beast in order to escape certain death and painful digestion.","ecology":"","habitat_society":""},{"name":"Young Adult Gray Dragon","cr":9,"xp":6400,"alignment":"NE","size":"Large","type":"dragon","subtypes":["water"],"init":5,"senses":[{"type":"dragon senses"}],"ac":26,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+1 Dex, +16 natural, -1 size","hp":115,"hd":"11d12+44","hdvalue":11,"fort":11,"ref":10,"will":9,"immunities":["paralysis","sleep"],"sr":20,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"2 claws +16 (1d8+6), bite +17 (2d6+9), 2 wings +14 (1d6+3), tail slap +14 (1d8+9)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"80-ft. line, 10d6 fire; DC 19 Ref half"}],"spellsknown_caster_level":3,"spellsknown_concentration":7,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"burning hands"},{"spell":"protection from good"},{"spell":"obscuring mist"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ray of frost"},{"spell":"resistance"}]}],"strength":23,"dexterity":12,"constitution":19,"intelligence":13,"wisdom":15,"charisma":13,"baseatk":11,"cmb":18,"cmd":29,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Fly","value":13},{"skill":"Intimidate","value":15},{"skill":"Knowledge (local)","value":15},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":11},{"skill":"Swim","value":28}],"languages":["Common","Draconic Special Abilities"],"environments":["warm coastlines"],"organizations":["solitary"],"treasure":"triple standard","description_visual":"Steam emanates from the nostrils and mouth of this slate gray dragon.","group":"Dragon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A gray dragon's breath weapon is a superheated line of steam."},{"type":"Change Shape","kind":"Su","details":"A young or older gray dragon can take any animal or humanoid form 3/day as if using polymorph."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older gray dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC 19) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is 180 ft."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A gray dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. • Young-fog cloud; • Juvenile-create water; • Old-control winds; • Ancient-control water;"},{"type":"Water Breathing","kind":"Ex","details":"A gray dragon breathes water and can use its breath weapon, spells, and abilities underwater."}],"description":"Gray dragons are evil dragons that inhabit mountains and hills near coastlines. They have little regard for other races and often enslave others to do their bidding. Adult and older gray dragons are rarely found without a retinue of humanoid slaves. Gray dragons mate for life and a single mated pair often terrorizes nearby villages, laying waste to those that oppose the dragon's will.","ecology":"","habitat_society":""},{"name":"Adamantine Wasp Swarm","cr":10,"xp":9600,"alignment":"N","size":"Fine","type":"construct","subtypes":["swarm"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":24,"ac_flat_footed":18,"ac_mods":"+6 Dex, +8 size, +0 natural","hp":82,"hd":"15d10","hdvalue":15,"fort":5,"ref":11,"will":5,"immunities":["weapon damage","construct traits","swarm traits"],"sr":21,"weaknesses":["swarm traits"],"speed":[{"type":"land","speed":5},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"swarm (3d6 plus poison)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 17"}],"strength":1,"dexterity":22,"wisdom":11,"charisma":2,"baseatk":15,"skills":[{"skill":"Fly","value":18}],"environments":["any"],"organizations":["solitary","cloud (2-4 swarms)","plague (5-8 swarms)"],"treasure":"none","description_visual":"The sound of metallic clicking drones in your ears as thousands of tiny metal insects descend from the air.","group":"Adamantine Wasp","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Swarm-injury, save Fort DC 17; frequency 1/round for 4 rounds; effect 1d4 Dexterity damage; cure 2 consecutive saves. A creature reduced to Dexterity 0 freezes solid (similar to a flesh to stone spell) for 1d4 hours as his body hardens into ice. If reduced to 0 or less hit points while frozen, the creature shatters into pieces and dies. The save DC is Constitution-based."}],"description":"The adamantine wasp is a flying construct capable of bringing down the most powerful of opponents with its deadly sting.\n\nAdamantine wasps are constructed by spellcasters and used to guard or patrol areas the creator wishes to keep \"off limits.\" From a distance, they resemble 1-foot long silver wasps, and some spellcasters further enhance this ruse by constructing fake nests nearby to detract would-be trespassers.\n\nAn adamantine wasp is 1-foot long and looks like its namesake only made out of metal. Its body is segmented like a normal wasp (head, thorax, and abdomen) and has carefully and delicately been fitted together to form the wasp. A wicked-looking adamantine stinger protrudes from its abdomen. Its wings are formed of paper-thin adamantine, specially treated during the construction process.\n\nAdamantine wasps, being constructs, are non-intelligent and are programmed to carry out simple tasks such as \"guard this room\" or \"attack any who enter here.\" When following their commands, adamantine wasps fight until destroyed. A swarm attacks by stinging its foes and injecting its blood-freezing poison.\n\nConstruction Creating an adamantine wasp swarm costs 10,000 gp. Assembling the \"body\" requires a successful DC 20 ADAMANTINE WASP SWARM CL 13th; Price 80,000 gp Requirements Craft Construct, fly, geas/quest, poison, limited wish, creator must be caster level 13th; Skill Craft (weapons) or Craft (armor) DC 18; Cost 45,000 gp","ecology":"","habitat_society":""},{"name":"Adult Gray Dragon","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"dragon","subtypes":["water"],"init":5,"senses":[{"type":"dragon senses"}],"auras":["frightful presence (180 ft., DC 18)"],"ac":29,"ac_touch":10,"ac_flat_footed":28,"ac_mods":"+1 Dex, +19 natural, -1 size","hp":149,"hd":"13d12+65","hdvalue":13,"fort":13,"ref":11,"will":11,"immunities":["paralysis","sleep"],"sr":21,"speed":[{"type":"land","speed":60},{"type":"fly","speed":200,"maneuverability":"average"},{"type":"swim","speed":40}],"melee":"2 claws +19 (1d8+7), bite +20 (2d6+10/19-20), 2 wings +17 (1d6+3), tail slap +17 (1d8+10)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"80-ft. line, 12d6 fire; DC 21 Ref half"}],"spellsknown_caster_level":5,"spellsknown_concentration":10,"spellsknown":[{"spell_level":2,"spell_slots":5,"spells":[{"spell":"blur"},{"spell":"eagle's splendor"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"magic missile"},{"spell":"obscuring mist"},{"spell":"protection from good"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"light"},{"spell":"ray of frost"},{"spell":"resistance"}]}],"strength":25,"dexterity":12,"constitution":21,"intelligence":15,"wisdom":17,"charisma":15,"baseatk":13,"cmb":21,"cmd":32,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":18},{"skill":"Fly","value":15},{"skill":"Intimidate","value":18},{"skill":"Knowledge (local)","value":18},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":23},{"skill":"Stealth","value":13},{"skill":"Swim","value":31}],"languages":["Aquan","Common","Draconic Special Abilities"],"environments":["warm coastlines"],"organizations":["solitary"],"treasure":"triple standard","description_visual":"Steam emanates from the nostrils and mouth of this slate gray dragon.","group":"Dragon","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A gray dragon's breath weapon is a superheated line of steam."},{"type":"Change Shape","kind":"Su","details":"A young or older gray dragon can take any animal or humanoid form 3/day as if using polymorph."},{"type":"Corrupt Water","kind":"Sp","details":"Once per day an adult or older gray dragon can stagnate 10 cubic ft. of still water, making it foul and unable to support water-breathing life. The ability spoils liquids containing water. Liquid-based magic items (such as potions) and items in a creature's possession must succeed on a Will save (DC 19) or become ruined. This ability is the equivalent of a 1st-level spell. Its range is 180 ft."},{"type":"Spell-Like Abilities","kind":"Sp","details":"A gray dragon gains the following spell-like abilities, usable at will upon reaching the listed age category. • Young-fog cloud; • Juvenile-create water; • Old-control winds; • Ancient-control water;"},{"type":"Water Breathing","kind":"Ex","details":"A gray dragon breathes water and can use its breath weapon, spells, and abilities underwater."}],"description":"Gray dragons are evil dragons that inhabit mountains and hills near coastlines. They have little regard for other races and often enslave others to do their bidding. Adult and older gray dragons are rarely found without a retinue of humanoid slaves. Gray dragons mate for life and a single mated pair often terrorizes nearby villages, laying waste to those that oppose the dragon's will.","ecology":"","habitat_society":""},{"name":"Baba Yaga","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fear (30 ft., DC 20)"],"ac":22,"ac_touch":14,"ac_flat_footed":18,"ac_mods":"+4 Dex, +8 natural","hp":114,"hd":"12d10+48","hdvalue":12,"fort":8,"ref":12,"will":14,"dr":"10/cold iron and magic","immunities":["charm","fear","sleep"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":30}],"melee":"2 claws +17 (1d6+5 plus grab), bite +17 (1d8+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"decaying hex","details":"DC 22"},{"type":"evil eye","details":"DC 22"},{"type":"rend","details":"2d6+7"}],"spellsprepared_caster_level":12,"spellsprepared_concentration":20,"spellsprepared":[{"spell_level":6,"spell_slots":1,"spells":[{"spell":"greater dispel magic"},{"spell":"flesh to stone"},{"spell":"mass suggestion"}]},{"spell_level":5,"spell_slots":1,"spells":[{"spell":"dominate person"},{"spell":"feeblemind"},{"spell":"hold monster"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"enervation"},{"spell":"ice storm"},{"spell":"poison"},{"spell":"scrying"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"bestow curse"},{"spell":"dispel magic"},{"spell":"fly"},{"spell":"screech"},{"spell":"spit venom"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"alter self"},{"spell":"death knell"},{"spell":"enthrall"},{"spell":"hold person"},{"spell":"touch of idiocy"},{"spell":"web"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"cause fear"},{"spell":"charm person"},{"spell":"dancing lantern"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"putrefy food and drink"},{"spell":"touch of fatigue"}]}],"strength":20,"dexterity":19,"constitution":19,"intelligence":23,"wisdom":18,"charisma":19,"baseatk":12,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":31,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Empower Spell"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Quicken Spell"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Intimidate","value":19},{"skill":"Knowledge (arcana)","value":18},{"skill":"Knowledge (nature)","value":22},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":20},{"skill":"Spellcraft","value":18},{"skill":"Stealth","value":19,"special":"+27 in swamps"},{"skill":"Use Magic Device","value":16}],"languages":["Abyssal","Common","Draconic","Giant","Infernal","Sylvan"],"sq":[{"type":"swamp stride"}],"environments":["temperate swamps"],"organizations":["solitary","coven (3)"],"treasure":"standard","description_visual":"This hideous crone has brownish-green flesh, a large nose and razor-sharp teeth.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Aura of Fear","kind":"Su","details":"This aura functions as a fear spell (CL 12th). A creature that successfully saves against the baba yaga's aura is unaffected by the same baba yaga's aura for one day. This is a mind-affecting effect. The save DC is Charisma-based. A baba yaga can suppress or restart this aura as a free action."},{"type":"Evil Eye","kind":"Su","details":"As a standard action, a baba yaga can crush the will of a foe within 30 ft. that she can see. The target must succeed on a DC 22 Will save or take a -4 penalty on attack rolls, saving throws, and skill checks until the evil eye is removed. This is a curse effect. The save DC is Intelligence-based. A creature currently affected by a baba yaga's evil eye cannot be affected again (by the same or a different."},{"type":"Decaying Hex","kind":"Su","details":"As a standard action, a baba yaga can place a hex on any living creature within 60 ft. If the creature fails a DC 22 Fortitude save it takes 3d6 points of damage plus 2d6 bleed damage. A creature that fails its save by 5 or more also takes 1d2 points of Constitution damage. The bleeding can be stopped with a DC 15 Heal check or through the application of any magical healing. The save DC is Intelligence-based. Spells A baba yaga casts spells as a 12th-level witch. They don't gain access to any other witch abilities."},{"type":"Swamp Stride","kind":"Ex","details":"A baba yaga can move through bogs and quicksand without penalty at its normal speed."}],"description":"Long thought to be a solitary or unique being (similar to the medusa), sages and scholars have come to believe the baba yaga are in fact a race of evil crones related to the hag race. Perhaps this theory is accurate, or perhaps it is what the true Baba Yaga wants the world to believe; no one is quite sure what is true and what isn't when it comes to the baba yaga.\n\nA baba yaga makes its home deep in the darkest and most remote swamps and fens. There in the center of the swamp is her home: a large wooden hut perched atop two tall and muscular chicken legs. The hut is believed to be highly magical, ten times larger on the inside than it appears outside, and possibly contain portals to other planes. It is also believed by some to be some sort of construct or golem, though no proof of such claims exists. Surrounding the hut is a small dark picket fence which holds the skulls of the baba yaga's victims. The hut can lower itself to the ground so the baba yaga can enter, but it only functions if she chants, and it only functions for the baba yaga that dwells there. No other creature has figured out how to control the baba yaga's hut.\n\nAdventurers who have seen a baba yaga on the move say she moves through her swampy lair at in a giant mortar, steering it with a large pestle in one hand, and using a magic broom to sweep all traces of her passing with the other. This mortar, rumors say, can only be driven by a baba yaga or high level spellcaster, but again, no one is certain what the truth is.\n\nA baba yaga appears as a slightly hunched, old, and hideously ugly crone, with a large nose, long sharp teeth, and hands that end in wicked claws. She dresses in loose fitting ugly brown cloaks. When moving about in civilized areas, a baba yaga often pulls the hood of her cloak over her head, walks slowly, and carries a crooked and rotting walking stick.","ecology":"","habitat_society":""},{"name":"Boarfolk","cr":10,"xp":9600,"alignment":"N","size":"Large","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 Dex, +6 natural, -1 size","hp":126,"hd":"13d10+42 (+13)","hdvalue":13,"fort":12,"ref":11,"will":5,"defensive_abilities":["ferocity"],"speed":[{"type":"land","speed":40}],"melee":"greatclub +20 (1d10+10), gore +20 (2d6+10)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"trample","details":"1d6+10, DC 23"}],"strength":24,"dexterity":16,"constitution":18,"intelligence":6,"wisdom":8,"charisma":8,"baseatk":13,"cmb":21,"cmb_special":"+2 vs. sunder","cmd":34,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Martial Weapon Proficiency (greatclub)"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":6},{"skill":"Stealth","value":6},{"skill":"Swim","value":15}],"languages":["boarfolk"],"sq":[{"type":"rage","details":"32 rounds/day"}],"environments":["temperate forests"],"organizations":["solitary","pair","club (4-9)"],"treasure":"no coins; 50% goods","description_visual":"A group of large, wild-pig-faced humanoids snort derisively and head towards you. They don't appear to be friendly at all.","source":"Tome of Horrors 4 (3pp)","description":"Boarfolk are giant humanoids standing some 9 to 10 ft. tall, weighing nearly 700 pounds. They possess boar-like features, including large tusks that protrude from their mouths.\n\nBoarfolk are created by the sorceress, Circe, on the Isle of the Phoenix, in the Land of the Dead. There she uses her powers to transmute travelers that are unfortunate enough to cross her path. Once transmuted the boarfolk grow enthralled by her beauty and charisma, and serve her without question.\n\nBoarfolk speak an offshoot of Common, but so thickly accented as to make it a separate language.\n\nThe boarfolk live in nomadic, tribal fashion. Should the influence of Circe ever depart, the boarfolk would turn to infighting and barbaric tribal law; the strongest would rule, and the rest of the boarfollk would split into warring tribes.","ecology":"","habitat_society":"","credit":"Original author William Loran Christensen  Originally appearing in Fane of the Fallen (© Frog God Games/ William Loran Christensen, 2010)","gear":"Greatclubs"},{"name":"Brume","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"aberration","subtypes":["evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense","modifier":"120 ft."}],"ac":21,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+3 Dex, +9 natural, -1 size","hp":110,"hd":"13d8+52","hdvalue":13,"fort":8,"ref":7,"will":10,"defensive_abilities":["insubstantial form"],"dr":"10/magic","immunities":["poison"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"2 claws +12 (1d6+1 plus 1d6 Cha)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"Charisma damage"},{"type":"memory loss"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"fog cloud"},{"spell":"obscuring mist"}]}],"strength":13,"dexterity":16,"constitution":19,"intelligence":14,"wisdom":14,"charisma":17,"baseatk":9,"cmb":11,"cmd":24,"feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (survival)"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Bluff","value":16},{"skill":"Diplomacy","value":12},{"skill":"Disguise","value":13},{"skill":"Fly","value":13},{"skill":"Intimidate","value":17},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":4},{"skill":"Survival","value":24}],"languages":["understands Abyssal","Common","Infernal"],"sq":[{"type":"insubstantial form"},{"type":"natural invisibility"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This semi transparent being has the appearance of a humanoid wrapped in a soggy funeral shroud. Long claws extend from the arms of the shroud, when its hood is thrown back a nose-less, ear-less face filled with needle like fangs and sunken black eye-sockets that glow with two wicked golden points of light. The creature has no apparent legs, seeming to hover inches from the ground, its \"ft.\" nothing more than foul swirling vapors.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Charisma Damage","kind":"Su","details":"Any creature touched or hit by a brume takes 1d6 points of Charisma damage. A creature reduced to Charisma 0 by a brume dies."},{"type":"Memory Loss","kind":"Su","details":"An opponent hit by a brume's claw attack must succeed on a DC 20 Will save or forget everything that has happened in the last 1d6 hours (treat this as a modify memory spell). The save DC is Constitution-based. Even if the save is successful, the opponent acts as if affected by a confusion spell (caster level 13th) for 2d4 hours. The confusion effects can be removed using break enchantment, dispel magic, or greater magic."},{"type":"Insubstantial Form","kind":"Ex","details":"A brume's insubstantial form gives it immunity to poison and critical hits. It cannot run, wear armor, or enter water or other liquids. It can pass through holes and small openings-even cracks. It can also occupy spaces occupied by its enemies. (This ability is similar to a gaseous form spell-note the brume isn't subject to wind effects like the gaseous form spell allows.) Any piercing or slashing attack against a brume has a 20% miss chance. Bludgeoning attacks deal damage normally."},{"type":"Lifesense","kind":"Su","details":"A brume can automatically pinpoint the location of any living creature within 120 ft., just as if it possessed the blindsight ability. It also senses the strength of their life force automatically, as if it had cast deathwatch."},{"type":"Natural Invisibility","kind":"Ex","details":"A brume is effectively invisible in fog, smoke, or mist."}],"description":"These strange creatures of extraplanar origin dwell within the mists of the Styx, where they are known to strangle the life from the living who finds themselves lost there. Brumes begin tracking enemies which enter their territory, seeking to steal personal effects from their target in an attempt to gain information about its strengths and weaknesses.\n\nBrumes are almost invisible in fog, making them difficult to spot and even harder to kill. They feed off the energy of lost souls, devouring the lost dead of Styx as readily as they do the living, absorbing whatever energy remains in its victims and leaving behind a dried husk in their wake.\n\nOccasionally brumes find their way into the material planes and reside near planar conduits and crossing points that lead into the Styx. Brumes may be bribed to act as guides through passage into Styx, but usually demand some form of living sacrifice in return.\n\nBrume are believed to understand several languages though they are not known to speak.\n\nBrumes rise from the mists, attacking with claws in an attempt to strangle their enemies silently and unseen. When faced with overwhelming numbers they seek to escape into the fog, where they bide their time, tracking foes over great distance, until such time that their foes leave the misty areas that they call home. Many who have been attacked by a brume and lived have no recollection of having fought them and seem withdrawn from others, having no memory of the attack itself and missing large pieces of their own identity.\n\nA brume's natural weapons are treated as magic weapons for the purpose of overcoming damage reduction. A brume's natural weapons, as well as any weapon it wields, are treated as evil-aligned for the purpose of overcoming damage reduction.","ecology":"","habitat_society":""},{"name":"Crimson Death","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"aberration","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+4 Dex, +10 natural","hp":127,"hd":"17d8+51","hdvalue":17,"fort":10,"ref":11,"will":15,"dr":"5/magic and silver","sr":21,"speed":[{"type":"land","speed":60,"special":"30 ft. after feeding"}],"melee":"2 tentacles +17 (1d6 plus engulf)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf","details":"DC 18, 1d6 plus 1d6 Con"}],"strength":11,"dexterity":18,"constitution":16,"intelligence":17,"wisdom":16,"charisma":16,"baseatk":12,"cmb":16,"cmd":26,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (tentacles)"}],"skills":[{"skill":"Climb","value":20},{"skill":"Escape Artist","value":24},{"skill":"Knowledge (dungeoneering)","value":23},{"skill":"Perception","value":29},{"skill":"Stealth","value":30,"special":"+42 in mist or fog"},{"skill":"Survival","value":23},{"skill":"Swim","value":20}],"languages":["Aklo (can't speak)"],"sq":[{"type":"susceptibility"}],"environments":["any swamps","any underground"],"organizations":["solitary"],"treasure":"incidental","description_visual":"Seemingly made of red vapor, the crimson mist is an outstanding stealth hunter. The crimson death is vaguely humanoid in appearance, with arms, torso and a head being discernible. The creature has no distinct facial features, other than 2 glowing points where eyes should be.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Engulf","kind":"Ex","details":"When a crimson death strikes a target with one of its tentacles, it can immediately make an engulf attack, including moving into the opponent's square. Targeted creatures can make attacks of opportunity against the crimson death, but if they do so, they are not entitled to a saving throw against the engulf attack. Those who don't attempt attacks of opportunity can attempt a Reflex (DC 18) save to avoid being engulfed-on a success, they are pushed back or aside (target's choice) as the crimson death moves forward. Engulfed opponents gain the pinned condition, are in danger of suffocating, are trapped within the crimson death's body until they are no longer pinned, and suffer 1d6 points of damage and 1d6 points of Constitution damage every round. A victim reduced to 0 Constitution dies. The save DC is Strength-based."},{"type":"Susceptibility","kind":"Ex","details":"After draining its victim's Constitution, the crimson death, sated from its feeding, moves at half its normal speed, loses its racial bonus to Stealth checks (because it flushes crimson, hence the name), and suffers a -4 circumstance penalty to AC. These effects last for 1 hour."}],"description":"A crimson death attacks from ambush, usually hiding in naturally occurring fog and waiting for potential prey to wander close. Often times, a crimson death uses sound (imitating cries for help, for example) in an attempt to lure a victim into its grasp.\n\nA crimson death can understand Aklo, although it doesn't speak.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Derghodaemon","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":12,"ac_flat_footed":21,"ac_mods":"+3 Dex, +12 natural, -1 size","hp":125,"hd":"10d10+60 (+10)","hdvalue":10,"fort":13,"ref":10,"will":7,"defensive_abilities":["all-around vision"],"dr":"10/cold iron or silver","immunities":["acid","flanking","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":40}],"melee":"5 claws +17 (1d6+8 plus grab) and bite +17 (1d8+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"feeblemind"},{"type":"rend","details":"2 claws, 2d6+12"},{"type":"tear"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"cause fear"},{"spell":"deeper darkness"},{"spell":"desecrate"},{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"2/day","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"sleep"}]}],"strength":26,"dexterity":16,"constitution":22,"intelligence":7,"wisdom":14,"charisma":16,"baseatk":10,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":32,"cmd_special":"+2 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":16},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":12}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"environments":["any land","any underground","any (Lower Planes)"],"organizations":["solitary","team (2-4)"],"treasure":"standard, plus 1d3 gems (100 gp value) in gizzard","description_visual":"This creature is a tall, bloated, insect-like creature with five arms and three legs. Each of its arms ends in a sharpened, clawed hand. Its legs end in four-toed ft. Its flesh is mottled green and black and its eyes are large and black with no pupils.","group":"Daemon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Feeblemind","kind":"Su","details":"Twice per day, by clattering its mandibles together, a derghodaemon can affect all creatures within 30 ft. as if by a feeblemind spell. Daemons are immune to this effect, but all other creatures must make a DC 18 Will save to resist its effects. The effect lasts for 6 rounds. This is a sonic mind-affecting effect. The save DC is Charismabased."},{"type":"Tear","kind":"Ex","details":"If a derghodaemon grapples an opponent, it automatically hits its opponent with all of its melee attacks each round following that it maintains its hold."}],"description":"The derghodaemon is one of the strongest of the daemon races, but its low intelligence has relegated it to a position of brute warrior and little more.\n\nA derghodaemon stands 8 ft. tall and weighs about 800 pounds.\n\nThe derghodaemon opens combat with its feeblemind attack. Opponents are then subjected to a barrage of claws or weapons, or a combination of both.\n\nA derghodaemon's natural weapons, as well as any weapons it wields, are treated as evil-aligned for the purpose of overcoming damage reduction.","ecology":"","habitat_society":"","credit":"The Derghodaemon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Devouring Mist","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"undead","subtypes":["swarm"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":9,"ac_mods":"+4 Dex, +1 dodge, -1 size","hp":133,"hd":"14d12+42","hdvalue":14,"fort":9,"ref":10,"will":-1,"save_mods":"Will: +2 vs. disease and mind-affecting effects","defensive_abilities":["channel resistance +4","swarm traits"],"immunities":["undead traits","weapon damage"],"sr":24,"weaknesses":["swarm traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"swarm (blood drain)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"create spawn"},{"type":"distraction","details":"DC 20"}],"strength":1,"dexterity":19,"intelligence":8,"wisdom":16,"charisma":16,"baseatk":10,"cmb":2,"cmd":15,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Channel Resistance"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Fly","value":27},{"skill":"Perception","value":26},{"skill":"Stealth","value":23,"special":"+33 in the Bloodways"}],"environments":["any underground (the Bloodways)"],"organizations":["solitary"],"treasure":"none","description_visual":"This drifting nightmare resembles a cloud of dark red vapor about 10 ft. in diameter.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Blood Drain","kind":"Ex","details":"Creatures in the devouring mist's space at the end of its movement each round take 1d4 points of Constitution damage as it siphons blood out of the victim's body. For every point so drained, the devouring mist heals 5 hit points of damage. Creatures without blood take no damage from the devouring mist."},{"type":"Create Spawn","kind":"Su","details":"Any creature slain by a devouring mist rises as a vampire spawn in 1d4 days, unless the remains are blessed. If the victim had more than 5 hit dice, there is a 1% chance per hit die that it arises as a full-fledged vampire instead, or a 5% chance per hit die if the victim was of the humanoid type."}],"description":"Spawned of the dreams of the Bloodwraith, devouring mists are undead composed of equal parts blood and malice, wedded together by negative energy. They drift the halls of the Bloodways, looking for living prey to feed on and torment. When they strike, they surround their enemies and draw their blood from their bodies.\n\nDevouring mists are possessed of a malicious cunning. They are quite capable of blending into the mists of the Bloodways so as to take their prey unaware. They may also follow creatures for a time and attack when they are distracted or preoccupied. A devouring mist may even stalk its prey over hours or even days, striking again and again, in effect milking them of blood.\n\nDevouring mists don't speak, nor can they be communicated with.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Dimensional Slug","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"magical beast","init":2,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":25,"ac_touch":7,"ac_flat_footed":24,"ac_mods":"-2 Dex, +1 dodge, +18 natural, -2 size","hp":126,"hd":"12d10+60","hdvalue":12,"fort":15,"ref":6,"will":2,"defensive_abilities":["ethereal jaunt"],"dr":"10/slashing or piercing","immunities":["acid"],"weaknesses":["vulnerability to salt"],"speed":[{"type":"land","speed":20}],"melee":"tongue +20 (2d10+10 plus 2d8 acid)","ranged":"spit +8 (12d6 acid)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"crush"},{"type":"ethereal ambush"}],"strength":31,"dexterity":6,"constitution":20,"intelligence":4,"wisdom":12,"charisma":10,"baseatk":12,"cmb":9,"cmd":21,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge","type":"bonus"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":14},{"skill":"Perception","value":10},{"skill":"Stealth","value":1}],"sq":[{"type":"malleable"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"none","description_visual":"This gigantic brownish-gray slug drips acid from its shimmering form.","group":"Slug","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Crush","kind":"Ex","details":"A dimensional slug can rear up and fall on its opponents, affecting as many Medium or smaller size opponents as it can cover. Opponents in the affected area must succeed on a DC 26 Reflex save or be pinned, automatically taking 2d8+15 points of bludgeoning damage during the next round unless the creature moves off them. If the creature chooses to maintain the pin, it must succeed at a combat maneuver check as normal. Pinned foes take damage from the crush each round if they don't escape. The save DC is Strength-based."},{"type":"Ethereal Ambush","kind":"Ex","details":"A dimensional slug that attacks foes on the Material Plane in a surprise round can take a full round of actions if it begins the combat by phasing into the Material Plane from the Ethereal Plane."},{"type":"Ethereal Jaunt","kind":"Su","details":"A dimensional slug can shift from the Ethereal Plane to the Material Plane as a free action, and shift back again as a move action (or as part of a move action). The ability is otherwise identical to ethereal jaunt (CL 15th)."},{"type":"Spit Acid","kind":"Ex","details":"A dimensional slug can spit acid at an opponent within 60 ft. (no range increment). With a successful ranged touch attack, the target takes 12d6 points of acid damage (no save)."},{"type":"Malleable","kind":"Ex","details":"A dimensional slug's body is very malleable, allowing it to fit into narrow areas with ease. A dimensional slug takes no penalty to its speed or checks when squeezing in an area that is one size category smaller than its actual size (10 ft. wide for most dimensional slugs). A dimensional slug can squeeze normally through an area two size categories smaller than its actual size (5 ft. wide for most dimensional slugs)."},{"type":"Vulnerability to Salt","kind":"Ex","details":"A handful of salt burns a dimensional slug as if the salt were a flask of acid, causing 1d6 points of damage per use."}],"description":"Dimensional slugs are offshoots of giant slugs that now dwell in the Ethereal Plane. They feed upon the detritus, which is sometimes drawn into the ether, and occasionally shift themselves into the Material Plane to feed. These creatures detest phase spiders and attack them on sight.\n\nA dimensional slug commonly attacks by spraying acid and crushing its opponents. If combat is going poorly for a dimensional slug, it shifts back to the Ethereal Plane.","ecology":"","habitat_society":""},{"name":"Dracohydra","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"magical beast","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+1 Dex, +11 natural, -2 size","hp":105,"hd":"10d10+50","hdvalue":10,"hp_mods":["fast healing 10"],"fort":11,"ref":10,"will":5,"defensive_abilities":["all-around vision"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"melee":"5 bites +14 (2d6+5/19-20)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"5 breath weapons","details":"30-ft. cone, DC 19, 4d6 damage; see text"},{"type":"savage bite"}],"strength":21,"dexterity":12,"constitution":19,"intelligence":6,"wisdom":11,"charisma":12,"baseatk":10,"cmb":14,"cmd":23,"cmd_special":"+8 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)","type":"bonus"}],"skills":[{"skill":"Intimidate","value":6},{"skill":"Perception","value":12},{"skill":"Swim","value":13}],"languages":["Common","Draconic"],"sq":[{"type":"hydra traits"},{"type":"regenerate head"}],"environments":["any"],"organizations":["solitary"],"treasure":"double standard","description_visual":"Five dragon-like heads of varying colors rise from the sleek, serpentine body of this hideous monster.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"Each of a dracohydra's heads has a single breath weapon. To determine each head's color and the associated breath weapon, choose from or roll on the table below. 1d10 Head Color Breath Weapon 1-2 Black Acid 3-4 Blue Electricity 5-6 Green Acid 7-8 Red Fire 9-10."},{"type":"White Cold Fast Healing","kind":"Ex","details":"A dracohydra's fast healing applies only to damage inflicted on the dracohydra's body."},{"type":"Hydra Traits","kind":"Ex","details":"A dracohydra can be killed by severing its heads or slaying its body. Any attack that isn't an attempt to sever a head affects the body, including area attacks or attacks that cause piercing or bludgeoning damage. To sever a head, an opponent must make a sunder attempt with a slashing weapon targeting a head. A head is considered a separate weapon with hardness 0 and 10 hit points. To sever a head, an opponent must inflict enough damage to reduce the head's hit points to 0 or less. Severing a head deals 10 points of damage to the dracohydra's body. A dracohydra can't attack with a severed head, but takes no other penalties."},{"type":"Regenerate Head","kind":"Ex","details":"When a dracohydra's head is destroyed, two heads regrow in 1d4 rounds. The heads are of the same color as the one that was severed. A dracohydra cannot have more than 10 heads at any one time. To prevent new heads from growing, at least 5 points of acid or fire damage (after overcoming the dracohydra's resistances) must be dealt to the stump (a touch attack to hit) before they appear. Acid or fire damage from area attacks can affect stumps and the body simultaneously. A dracohydra doesn't die from losing its heads until all are cut off and the stumps seared by acid or fire."},{"type":"Savage Bite","kind":"Ex","details":"A dracohydra applies 1-1/2 times its Strength bonus to damage dealt with its bite attack, and it threatens a critical hit on a 19-20."}],"description":"Believed to be either the mating of a hydra and a dragon or the offspring of a draconic deity, the dracohydra is truly a fearsome monster. Most intelligent creatures do their best to avoid trespassing on a dracohydra's domain for these creatures are extremely territorial, even more so than some dragons. Dracohydras prefer lairing in remote locations such as mountaintops and ruins, far away from civilization and far away from adventurous treasure seekers.\n\nDracohydras, while solitary, often make pacts with local humanoids; most often orcs, gnolls, and hobgoblins. Generally these pacts are lopsided deals that favor the dracohydra: give it food and it won't eat your village. Such food usually consists of herd animals or cattle, and sometimes humanoids if necessary to sate the dracohydra's voracious appetite. Humanoid sacrifices usually take the form of slaves or prisoners, but if either of those is in low numbers, tribes have been known to sacrifice their own to appease a dracohydra.\n\nBetraying their draconic origin, dracohydras amass treasure in great quantities. Most treasures are left strewn about the lair, but some, such as rare gemstones and small trinkets are devoured by dracohydras.\n\nDracohydras don't associate with other dracohydras, hydras, or dragons. Hydras are particularly reviled for unknown reasons, and are attacked on sight and slaughtered, their bodies being almost completely devoured by a dracohydra.\n\nA dracohydra's body is usually dark gray or dark grayish-blue. Its dragon-like heads are scaled and vary in color blending into the body at the neckline. A dracohydra's eyes are always sapphire blue, regardless of the color of the dragon's head.","ecology":"","habitat_society":""},{"name":"Dragonship","cr":10,"xp":9600,"alignment":"N","size":"Gargantuan","type":"construct","init":-3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":3,"ac_flat_footed":23,"ac_mods":"-3 Dex, +20 natural, -4 size","hp":170,"hd":"20d10+60","hdvalue":20,"fort":6,"ref":3,"will":21,"dr":"15/adamantine","immunities":["construct traits"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"swim","speed":40}],"melee":"bite +25 (1d8+9), 4 slams +25 (2d6+9)","space":"20 ft.","reach":"15 ft. (20 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"30-ft. cone, 10d6 fire damage, Reflex DC 20 for half, usable 3/day"}],"strength":28,"dexterity":4,"wisdom":10,"charisma":10,"baseatk":20,"cmb":33,"cmd":42,"cmd_special":"can't be tripped","skills":[{"skill":"Swim","value":17}],"sq":[{"type":"navigate"},{"type":"winds"}],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"none","description_visual":"This automaton appears as a massive wooden longship sculpted to grant it a dragonlike appearance, with a scaled hull, a bow curving up to form a dragon's head, and a stern tapering to a tail.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Navigate","kind":"Ex","details":"A captain merely has to whisper into the ear of the dragon-head and make a Profession (sailor) check (DC 15) to get the dragonship to understand its course. A dragonship never gets lost on an ocean voyage, and has a 50% chance of automatically being aware of any safe coastline, seaside towns and villages, and hidden ocean dangers such as reefs and sandbars (it only knows of such dangers if they are in the volume of sea charts used in its creation)."},{"type":"Winds","kind":"Su","details":"At will, a dragonship can cause winds to fill its sails. This operates as the control winds spell (caster level 10th) with the restriction that it can only increase the wind's force for the purposes of propulsion. The winds are generated from a point beyond and slightly above the dragonship's stern. A dragonship cannot use these winds to attack; their sole purpose is propulsion."}],"description":"A dragonship is an animated sailing vessel-essentially a massive wood golem in the form of a longship. It is identical to a longship in every way except that it is only 20 ft. long. It has a standard square-rigged sail, and 10 oars (5 on each side). Using its oars or its ability to generate winds on its own, a dragonship is rarely at the mercy of the weather. It has an instinctive understanding of local sea charts and navigation routes. Its primary function is as a transport that needs no crew; it can be told one's destination and it will sail there by the quickest route possible.\n\nAlthough generally used as a warship, a dragonship's primary function is that of a sailing vessel. A dragonship isn't particularly adept at combat and it cannot maneuver to defend itself if it is beached; in such cases it relies on its crew for defense. A dragonship bites and breathes fire with its dragon-like head, and can use up to four oars to slap at foes that approach from the flanks.\n\nAs a sailing vessel a dragonship can carry up to 30 passengers and up to 35 tons of cargo. Its speed is that of a normal longship.\n\nConstruction A dragonship's body is a constructed similar to a normal longship fitted with a dragon-head mounted on the bow. The ship costs 10,000 gp and the figurehead costs 1,000 gp. Also required is a volume of sea charts and maps (total value at least 200 gp), to be burned in the mouth of the dragonship's head upon completion of its construction. Consumed in the fire, the distilled knowledge of the sea charts provides the dragonship with its ability to navigate.\n\nDRAGONSHIP CL 16th; Price 99,200 gp Requirements Craft Construct, fireball, geas/quest, limited wish, liveoak, polymorph any object, creator must be caster level 16th; Skill Craft (shipbuilding) DC 20; Cost 55,200 gp","ecology":"","habitat_society":""},{"name":"Elder Salt Elemental","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["dehydration (20 ft., DC 20, 2d10)"],"ac":21,"ac_touch":9,"ac_flat_footed":20,"ac_mods":"+1 Dex, +12 natural, -2 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":12,"ref":5,"will":8,"dr":"10/-","immunities":["elemental traits"],"weaknesses":["vulnerability to water"],"speed":[{"type":"land","speed":20}],"melee":"2 claws +18 (2d8+7 plus salt poisoning)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"salt poisoning","details":"15 rounds, DC 20"}],"strength":25,"dexterity":13,"constitution":19,"intelligence":10,"wisdom":11,"charisma":11,"baseatk":12,"cmb":21,"cmd":33,"feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Step Up"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Climb","value":22},{"skill":"Intimidate","value":12},{"skill":"Knowledge (dungeoneering)","value":15},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":15},{"skill":"Stealth","value":8}],"languages":["Terran"],"environments":["any (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This crystalline humanoid is slightly translucent and light gray in color. Its head has no discernible features and its power arms end in massive fists.","group":"Elemental","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Dehydration Aura","kind":"Su","details":"A salt elemental's aura draws moisture from an area centered on itself. Living creatures within range take damage (damage is detailed with each elemental) each round they remain in the area. A successful Fortitude save reduces the damage by half. This effect is especially devastating to plants, animals, and aquatic creatures, which take a -4 penalty on their saving throws. The save DC is Constitution-based."},{"type":"Earth Mastery","kind":"Ex","details":"A salt elemental gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks. (These modifiers are not included in the statistics block.)"},{"type":"Salt Poisoning","kind":"Ex","details":"Anyone hit by a salt elemental's claw attack is sickened for 3 rounds + 1 round per Hit Dice of the salt elemental. A successful Fortitude save negates this effect. The save DC is Constitution-based."},{"type":"Vulnerability to Water","kind":"Ex","details":"A salt elemental submerged in water that covers at least half its body takes 1d6 points of damage each round until it escapes. Damage from water-based attacks (such as the slam attack of a water elemental) deal +50% damage to a salt elemental."}],"description":"Salt elementals inhabit regions rich in salt upon the Plane of Earth. Some believe they originated on a pocket plane somewhere near the energy planes and Plane of Water; perhaps an Elemental Plane of Salt. Salt elementals, avoid large expanses of water at all costs, knowing exposure to such a large quantity spells disaster.\n\nSalt elementals spend most of their time wandering their realm and often make forays into other planes (except the Plane of Water), seeking creatures on which to feed. They are particularly fond of plants, which are extremely vulnerable to their dehydrating ability.\n\nA salt elemental generally appears as a humanoid with no discernible features, though they can take other forms, and some do, preferring to appear in the shape of large animals or giant vermin (usually beetles).","ecology":"","habitat_society":""},{"name":"Festering Lung","cr":10,"xp":9600,"alignment":"N","size":"Medium","type":"vermin","subtypes":["swarm"],"init":5,"senses":[{"type":"lifesense","modifier":"60 ft."}],"ac":15,"ac_touch":15,"ac_flat_footed":10,"ac_mods":"+5 Dex","hp":52,"hd":"15d8-15","hdvalue":15,"hp_mods":["fast healing 10"],"fort":8,"ref":10,"will":5,"defensive_abilities":["evasion"],"immunities":["mind-affecting effects","weapon damage","swarm traits","vermin traits"],"weaknesses":["swarm traits","vulnerability to remove disease"],"speed":[{"type":"fly","speed":10,"maneuverability":"perfect"}],"melee":"swarm (disease)","space":"5 ft.","reach":"0 ft.","special_attacks":[{"type":"disease"},{"type":"distraction","details":"DC 16"}],"dexterity":20,"constitution":8,"wisdom":10,"charisma":1,"baseatk":11,"feats":[{"feat":"Ability Focus (disease)","type":"bonus"}],"skills":[{"skill":"Fly","value":13},{"skill":"Stealth","value":5,"special":"+21 in darkness"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A cloud rises before you like a dark smear in the air, the smell of death in its wake.","group":"Living Disease","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Any creature whose space is occupied by the living disease at the end of its move is exposed to the form of disease of which the swarm is composed. Such a creature must succeed at a Fortitude save each round that it is in the swarm or take ability damage for that round as indicated under the disease type. There is no incubation period for this type of exposure and its method of delivery is irrelevant due to the sheer concentration of disease organisms present. Even after a creature leaves the area of a swarm, it must make the appropriate Fortitude save or continue to take ability damage each day as indicated by the disease. At this point two successful saving throws in a row indicate that the creature has fought off the disease and recovers, taking no more damage. However, the disease can be contracted again through regular exposure or another encounter with a living disease. Once a creature has made a successful saving throw against the disease of a living disease, it is immune to future bouts of disease of that particular living disease for 1 year. Festering Lung: This infection gets into the lungs of the affected creature and begins to break down the respiratory system, producing choking and copious amounts of bloody phlegm. It saps the strength from the victim due to poor oxygenation and renders him unable to speak or make any vocal noises two days after contraction. Creatures that don't breathe are immune to festering lung. Festering Lung: Swarm-inhaled; save DC 24 Fort; onset immediate; frequency 1/day; effect 1d4 Str damage and 1d4 Con damage; cure 2 consecutive saves. The save DC is Dexterity-based."},{"type":"Evasion","kind":"Ex","details":"Due to its composition of billions of highly resilient microscopic organisms, if it makes a Reflex saving throw against an attack that normally deals half damage on a successful save, a living disease instead takes no damage. It is identical to the rogue ability of the same name."},{"type":"Lifesense","kind":"Ex","details":"The overpowering drive to propagate itself gives a living disease the ability to notice and locate living creatures within 60 ft., just as if it possessed the blindsight ability."},{"type":"Vulnerability to Remove Disease","kind":"Ex","details":"If a remove disease is cast on a living disease or a victim currently in a space occupied by a living disease and the living disease fails a Fortitude save against the spell, it deals 5d10 points of damage to the living disease. A creature that has remove disease cast on it isn't cured unless outside of the swarm's area when the spell is cast or unless the living disease was destroyed by the casting of the spell. Otherwise, an infected creature will require an additional remove disease upon leaving the living disease's space if it contracted the disease while within."}],"description":"Living diseases are swarms of microscopic organisms, harmful bacteria or viruses that have supernaturally gained limited sentience as a cohesive swarm under certain exceedingly foul or magical conditions. They seek out hosts through which to propagate their contagion. Though they are considered swarms, their individual components are so small as to be invisible to unaided sight, exponentially smaller than even Fine creatures, and they are thus considered one Medium creature. They are only visible at all due to the sheer number of individual organisms that comprise the swarm; literally billions of them make up a single living disease.\n\nLiving diseases offer no resistance to items or creatures entering their midst and cannot be physically felt. They make no sound whatsoever. A living disease in the dark is terrible indeed, as there is no indication it is present until its effects are first felt.\n\nLiving diseases neither see nor sleep. Their movements are by pure instinct, and they locate potential hosts with their lifesense. Because of their resilience and extremely high reproductive rate, the microorganisms of a living disease give it fast healing 10.\n\nThough extremely rare, there are many different kinds of living diseases - potentially as many kinds as there are diseases. Two in particular are described here: festering lung and black rot.\n\nA living disease seeks to surround any potential host it senses. It instinctively avoids undead, oozes, plants and constructs, which don't make suitable hosts for the spreading of disease. Unlike normal swarms, a living disease doesn't deal physical damage. Instead it exposes any creature whose space it occupies at the end of its move to its form of disease.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Fire Whale","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["extraplanar","fire"],"init":1,"senses":[{"type":"blindsight","modifier":"120 ft."}],"ac":19,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+1 Dex, +10 natural, -2 size","hp":136,"hd":"12d10+72","hdvalue":12,"fort":14,"ref":9,"will":7,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"swim","speed":40}],"melee":"bite +22 (3d6+12), tail slap +19 (1d6+6)","space":"10 ft.","reach":"15 ft.","special_attacks":[{"type":"scalding blast"}],"strength":35,"dexterity":13,"constitution":23,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":12,"cmb":26,"cmd":37,"feats":[{"feat":"Awesome Blow"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":14},{"skill":"Swim","value":29}],"sq":[{"type":"hold breath"}],"environments":["any (Elemental Plane of Fire; Sea of Fire)","any (Plane of Molten Skies; Sea of Fire)"],"organizations":["solitary","pod (4-9)"],"treasure":"none","description_visual":"Surfacing from the sea of flames rises, a titanic crimson whale mottled with pattern of yellow and orange spots running down its dorsal fins. Its huge, angular mouth hangs open, exposing its hideous gaping gullet.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Hold Breath","kind":"Ex","details":"A fire whale can hold its breath for 8 x its Constitution score before it risks drowning."},{"type":"Scalding Blast","kind":"Su","details":"As a full round action, a fire whale can release a blast of superheated air from its blowhole that scalds or burns those contacting it. The cone-shaped blast has a range of 60 ft and deals 12d6 points of damage. A successful DC 22 Reflex save halves the damage. The save DC is Constitution-based. Once a fire whale uses this ability, it must wait 1d4 rounds before using its scalding blast again. After using this ability four times, the fire whale must submerge for at least two full rounds before it can use it again."}],"description":"All manner of fiery aquatic life swims the Sea of Fire, including the majestic fire whales. These 30-foot long mammals are relatively peaceful creatures, though if provoked they quickly become deadly adversaries. Fire whales generally spend their time feeding on elemental invertebrates that move along the bottom of the Sea of Fire. When feeding, the fire whale dives to the bottom, flips on its side, and swims along, running its head through the fiery and oily sea floor scooping food into its mouth. Fire whales generally take in enough food to sustain themselves for 4 months (during breeding season). Late in the year (by Material Plane standards) fire whales gather for their mating ritual. During this time as many as 7 fire whales can be encountered together. Sages are unsure as to the purpose of the \"extra\" fire whales, but each spends its share rolling and milling with the others during this ritual. Gestation for fire whales is generally 11 months after which time the mother gives birth to 1d2 calves. While the calves are growing, both they and the mother spend most of their time in the shallower ends of the Sea of Fire. After nearly 7 months, they migrate to deeper waters and most calves swim away and become independent. Young reach maturity around 6 years of age. Fire whales are hunted by various races for their meat, blubber, and oil. Of the races that hunt them the most are the salamanders, volcano giants (see their entry in this book), and the efreet of the City of Brass. Fire whales are generally peaceful creatures and rarely attack unless threatened. If forced into combat, a fire whale attacks with its bite and tail slap. Surface creatures that threaten a fire whale are subjected to its scalding blast attack.","ecology":"","habitat_society":""},{"name":"Gelatinous Golem","cr":10,"xp":9600,"alignment":"N","size":"Large","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+1 Dex, +14 natural, -1 size","hp":114,"hd":"13d10+30 (+13)","hdvalue":13,"fort":6,"ref":7,"will":6,"dr":"10/bludgeoning and magic","immunities":["construct traits","electricity","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +19 (2d6+6 plus 2d6 acid and paralysis)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"acid"},{"type":"engulf"},{"type":"paralysis","details":"3d6 rounds, DC 16"}],"strength":22,"dexterity":12,"intelligence":3,"wisdom":11,"charisma":1,"baseatk":8,"cmb":15,"cmd":26,"feats":[{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Lighting Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":19}],"sq":[{"type":"transparent"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This automaton looks like a humanoid-shaped semi-transparent amoeba. Small indentions appear to serve as the creature's eyes. No other facial features are present.","group":"Golem","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"A gelatinous golem's acid doesn't harm metal or stone."},{"type":"Engulf","kind":"Ex","details":"A gelatinous golem can try to wrap an opponent up to one size smaller than itself in its body as a standard action. The gelatinous golem attempts a grapple that doesn't provoke an attack of opportunity. If it wins the grapple the gelatinous golem establishes a hold. Attacks that hit an engulfing gelatinous golem deal half their damage to the golem and half to the engulfed victim. An engulfed opponent is subjected to the gelatinous golem's paralysis and acid each round it remains trapped. A trapped opponent can do nothing other than attempt to escape. Further, an engulfed foe must hold its breath or begin drowning. While engulfing an opponent, a gelatinous golem isn't considered grappled and can move and attack normally."},{"type":"Immunity to Magic","kind":"Ex","details":"A gelatinous golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against the creature, as noted below. A cone of cold spell slows it (as the slow spell) for 2d6 rounds, with no saving throw. An acid fog spell heals all of its lost hit points."},{"type":"Transparent","kind":"Ex","details":"A gelatinous golem is hard to see, even under ideal conditions, and it takes a DC 15 Perception check to notice one. Creatures who fail to notice a gelatinous golem and walk into it are automatically grappled (if the golem chooses to grapple the opponent)."}],"description":"Gelatinous golems are the creation of Jubilex the Faceless Lord or rather the invention of Jubilex and the creation of his priests. Formed of dead and preserved gelatinous cubes and infused with a spark of intelligence, these monsters are used by many of his priests as temple and tomb guardians. They share a link with ooze golems in that they co-exist in temples dedicated to The Faceless Lord. Like most golems, these automatons follow the orders of their creator, but being intelligent, they understand more complex instructions and can carry out more difficult tasks that ordinary constructs cannot. A gelatinous golem stands 8 ft. tall and weighs 600 pounds. A gelatinous golem cannot speak or make any vocal noise. It walks and moves with a slow and clumsy gait. A gelatinous golem attacks by smashing its opponents with its fists that exude an anesthetizing slime. Paralyzed opponents are ignored if other opponents continue attacking the golem. If all opponents are paralyzed, the golem carries out the commands of its creator (whether it is to kill such creatures, leave them alone, or some other such command). Construction A gelatinous golem's body is formed from a single dead gelatinous cube of Large or larger size and treated with a mixture of rare chemicals worth 1,000 gp. GELATINOUS GOLEM CL 12th; Price 85,000 gp Requirements Craft Construct, acid fog, geas/quest, limited wish, polymorph any object, creator must be caster level 12th; Skill Craft (sculptures) DC 17; Cost 43,000.","ecology":"","habitat_society":""}];
